package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class MultiplyAddContextsTest {
 @Test public void all9400ConditionsCheckPublicGivensAndGenericBlankHelp(){Set<String> sig=new HashSet<>();for(String id:List.of(MultiplyAddContexts.BOXES,MultiplyAddContexts.LINKS))for(int i=0;i<MultiplyAddContexts.count(id);i++){Question q=MultiplyAddContexts.indexed(id,i);assertTrue(sig.add(q.signature()));int[] v=MultiplyAddContexts.read(q);assertNotNull(v);q.answers=new String[]{"poison"};q.expression="poison";int expected=0;if(id.equals(MultiplyAddContexts.BOXES)){for(int box=0;box<v[1];box++)expected+=v[0];expected+=v[2];}else{for(int first=0;first<v[0];first++)for(int second=0;second<v[1];second++)expected++;}assertEquals(expected,v[4]);assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(expected+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(id.equals(MultiplyAddContexts.BOXES)?6:3,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] values=id.equals(MultiplyAddContexts.BOXES)?new int[]{v[0]/10*10,v[0]%10,v[0]/10*10*v[1],v[0]%10*v[1],v[3],v[4]}:new int[]{v[1],v[0],v[4]};for(int stage=0;stage<h.size();stage++){assertTrue(h.step(stage).accepts(""+values[stage]));assertFalse(h.step(stage).before.matches("(?s).*[0-9].*"));}}assertEquals(9400,sig.size());}
 @Test public void realSupplyFreshAndAllThreeYear4AreasHaveNormalPlacement(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");GlobalCurriculum.Pack pack=GlobalCurriculum.pack(p);Generator gen=new Generator(new Random(149));for(String id:List.of(MultiplyAddContexts.BOXES,MultiplyAddContexts.LINKS)){assertTrue(pack.inGrade(id,4));assertFalse(pack.inGrade(id,3));CurriculumLimits limits=GlobalCurriculum.limits(pack.id,id,4);List<String> recent=new ArrayList<>();for(int i=0;i<300;i++){Question q=gen.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(MultiplyAddContexts.read(q));}Map<String,Integer> full=new LinkedHashMap<>();for(int i=0;i<MultiplyAddContexts.count(id);i++)full.put(MultiplyAddContexts.indexed(id,i).signature(),i);assertEquals(MultiplyAddContexts.indexed(id,0).signature(),MultiplyAddContexts.next(id,new Random(1),limits,full).signature());}assertTrue(pack.inGrade(ProductContextStories.SCALE,3));assertTrue(pack.inGrade(ProductContextStories.SCALE,4));}
 @Test public void zeroBoxesAndMaximumNetworksAndMalformedGivens(){assertArrayEquals(new int[]{99,0,9,0,9},MultiplyAddContexts.read(MultiplyAddContexts.make(MultiplyAddContexts.BOXES,99,0,9)));assertEquals(400,MultiplyAddContexts.read(MultiplyAddContexts.make(MultiplyAddContexts.LINKS,20,20,0))[4]);Question q=MultiplyAddContexts.make(MultiplyAddContexts.LINKS,1,1,0);q.prompt=q.prompt.replace("한쪽 점: 1개","한쪽 점: 21개");assertNull(MultiplyAddContexts.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1")).status);}
}
